// Without generics - loses type info
function firstElement(arr: any[]): any {
  return arr[0];
}

// With generics - preserves type info
function firstElement<T>(arr: T[]): T | undefined {
  return arr[0];
}

const numbers = [1, 2, 3];
const first = firstElement(numbers); // Type: number | undefined

const names = ['Alice', 'Bob'];
const firstName = firstElement(names); // Type: string | undefined

interface ApiResponse<T> {
  data: T;
  status: number;
  message: string;
}

// Usage
type UserResponse = ApiResponse<User>;
type UsersResponse = ApiResponse<User[]>;

// Generic component props
interface ListProps<T> {
  items: T[];
  renderItem: (item: T) => ReactNode;
  keyExtractor: (item: T) => string;
}

// TypeScript Example with Advanced Types
interface ApiResponse<T> {
  data: T;
  status: number;
  message: string;
  timestamp: Date;
}

// Utility type for partial updates
type PartialUser = Partial<{
  id: number;
  name: string;
  email: string;
  role: 'admin' | 'user' | 'guest';
}>;

// Generic function with constraints
async function fetchApi<T>(
  endpoint: string,
  options?: RequestInit
): Promise<ApiResponse<T>> {
  const response = await fetch(endpoint, {
    headers: {
      'Content-Type': 'application/json',
      ...options?.headers,
    },
    ...options,
  });

  if (!response.ok) {
    throw new Error(`API error: ${response.status} ${response.statusText}`);
  }

  return response.json();
}

// Type guard function
function isSuccessResponse<T>(
  response: ApiResponse<T>
): response is ApiResponse<T> & { status: 200 } {
  return response.status === 200;
}

